let g=text(20,30,tr('源表 h / mm','Source h / mm'),'font-weight="700"')+text(520,30,tr('选中窗口 / mm（校正前）','Selected window / mm (before correction)'),'font-weight="700"');
function tableGrid(data,js,x,width){let s='',cw=width/js.length;for(let k=0;k<js.length;k++)s+=text(x+(k+.5)*cw,64,`${T[js[k]]}`,'text-anchor="middle"');for(let i=0;i<3;i++){s+=text(x-16,110+i*70,['A','B','C'][i],'text-anchor="end"');for(let k=0;k<js.length;k++){let changed=i===p.row&&js[k]===p.start; s+=`<rect x="${x+k*cw}" y="${78+i*70}" width="${cw-3}" height="62" fill="${C[i]}" fill-opacity="${changed?.2:.09}" stroke="${changed?'#b85336':'#b8c5c8'}" stroke-width="${changed?2:1}"/>`+text(x+(k+.5)*cw,115+i*70,f(data[i][k]),'text-anchor="middle"');}}return s;}
