let values=relative.flat(),lo=Math.floor(Math.min(0,...values)/10)*10,hi=Math.max(10,Math.ceil(Math.max(...values)/10)*10);const x=t=>90+t/60*770,y=v=>315-(v-lo)/(hi-lo)*240;
