for(let v=lo;v<=hi;v+=10)s+=`<line x1="90" x2="860" y1="${y(v)}" y2="${y(v)}" stroke="#dce1df"/>`+text(78,y(v)+5,v.toString(),'text-anchor="end"');
for(let i=0;i<3;i++){s+=`<polyline points="${indices.map((j,k)=>`${x(T[j])},${y(relative[i][k])}`).join(' ')}" fill="none" stroke="${C[i]}" stroke-width="3"/>`;for(let k=0;k<indices.length;k++)s+=`<circle cx="${x(T[indices[k]])}" cy="${y(relative[i][k])}" r="5" fill="${C[i]}"/>`;s+=text(610+i*90,55,['A','B','C'][i],`style="fill:${C[i]}"`);}
