function set(q){p={...p,...q};for(const k of ['start','end'])p[k]=Math.max(0,Math.min(4,Math.round(Number(p[k]))));if(p.start>p.end){if('start'in q)p.end=p.start;else p.start=p.end;}p.row=Math.max(0,Math.min(2,Math.round(Number(p.row))));p.delta=Math.max(0,Math.min(.2,Number(p.delta)));p.drift=Math.max(0,Math.min(2,Number(p.drift)));render();return result;}
for(const k of ['start','end','row','mode'])$(k).addEventListener('change',()=>set({[k]:k==='mode'?$(k).value:Number($(k).value)}));for(const k of ['delta','drift'])$(k).addEventListener('input',()=>set({[k]:Number($(k).value)}));function reset(){p={...defaults};render();return result;}$('reset').addEventListener('click',reset);window.CourseLab={reset,set,state:()=>JSON.parse(JSON.stringify(result))};reset();
